function meta(n){return skills[n]||null}

// MP fields remain zero only for old battle/save protocol compatibility.
function derived(a){const d=legacyDerived(a);return {hp:d.hp,sp:100}}
function migrateVitals(v,a,version=0,saveVersion=7){
 const m=derived(a),old=legacyDerived(a),x={...(v||{})};
 if(version<1){
  if(saveVersion<5){const raw={hp:a[0],sp:a[0]+a[1]*2,mp:a[2]+a[3]};for(const k of ['hp','sp','mp'])x[k]=Math.round(old[k]*Math.min(1,Math.max(0,Number(x[k]??raw[k]))/raw[k]));}
  x.sp=Math.max(0,Number(x.sp??old.sp))+Math.max(0,Number(x.mp??old.mp));
 }
 const hp=Math.max(0,Math.min(m.hp,Number(x.hp??m.hp))),sp=Math.max(0,Math.min(m.sp,Number(x.sp??m.sp)));
 delete x.mp;
 return {...x,hp,sp};
}
